1	// The verify-in-production skill (#1091) rides the request lane — the queue is the
2	// delayed-execution mechanism, so the skill's whole contract is prose. These pin
3	// the parts the machinery depends on; the Not-before adoption carry it leans on is
4	// engine behaviour, tested in packs/claudinite-tasks/test/queue/request-mode.test.mjs.
5	import { test } from 'node:test';
6	import assert from 'node:assert/strict';
7	import { readFileSync } from 'node:fs';
8	import { join, dirname } from 'node:path';
9	import { fileURLToPath } from 'node:url';
10	
11	const skill = readFileSync(
12	  join(dirname(fileURLToPath(import.meta.url)), '../skills/verify-in-production/SKILL.md'), 'utf8');
13	
14	test('the skill carries the discernment test — most changes file nothing', () => {
15	  assert.match(skill, /file nothing/i,
16	    'the skill never says which changes file nothing, so every change would file one');
17	});
18	
19	test('what it files is a request the queue adopts, not a mechanism beside it', () => {
20	  assert.match(skill, /`task:origin:ad-hoc`/, 'the mark is what makes the scheduler run adopt the issue');
21	  assert.match(skill, /Not-before:/, 'without the delay the run fires before the release it waits on');
22	  assert.doesNotMatch(skill, /Automerge:.*apply/i, 'a verification has nothing to merge');
23	});
24	
25	// FILED ONLY AFTER THE MERGE (#1128). A PR can be REJECTED, and the queue cannot tell
26	// that from a merge: `readiness.mjs` releases a blocked item when its blocker is
27	// `closed`, and nothing anywhere reads `merged`. A verification filed pre-merge against
28	// a PR that is then rejected reads an `In-production-when:` that can never come true,
29	// re-arms silently by `Retry-every:` forever, and no janitor rule reclaims it — rule A
30	// cannot see an item sleeping on a future `Not-before`, and rule C exempts one whose
31	// blockers have closed. So the trigger moves to the merge and the field that
32	// accommodated the early file goes away.
33	test('the brief is filed only after the merge, and carries no PR blocker', () => {
34	  assert.match(skill, /after the merge, never before/i,
35	    'nothing stops a session filing this the moment the PR opens');
36	  assert.match(skill, /rejected/i,
37	    'the skill never says a rejected PR is why filing early is wrong');
38	  assert.doesNotMatch(skill, /^Blocked-by:/m,
39	    'the template still tells the filer to block on the PR — the field that invited the premature file');
40	});
41	
42	// The verification is AUTOMATIC end to end: the filed check must be one the run can
43	// read from HERE, and a person is a rare exception rather than the fallback.
44	//
45	// Which reads those are is the half that was missing (#1500): "an unattended run can
46	// make" is a property a filer will assume of anything it can read ITSELF, and five of
47	// one batch's seven claimed items parked on a dashboard or a cross-repo read nobody
48	// had checked the runner could reach. The half after that (#1520): an unreadable
49	// artifact must READ AS A REASON NOT TO FILE, not as a routing decision — three items
50	// naming a member repo were filed against a queue whose sessions are scoped to this
51	// one, and parked minutes after being picked.
52	test('the check is automatic by construction, and a human is the last resort', () => {
53	  assert.match(skill, /which tool call the run makes/i,
54	    'nothing makes the filer test Verify: against a read the runner can actually make');
55	  assert.match(skill, /file\s+nothing\*\*/i,
56	    'an unreadable artifact still reads as a form to file rather than a reason to stop');
57	  assert.match(skill, /rare exception/i,
58	    'the skill never bounds when a person may be asked at all');
59	});
60	
61	// A failed verification routes back to the ORIGINAL issue — reopened, with the
62	// status commented — so the filer's brief must carry that issue's number.
63	test('a failing run reopens the original issue the filed brief names', () => {
64	  assert.match(skill, /Original-issue:/);
65	  assert.match(skill, /reopen/i);
66	});
67	
68	// The hierarchy, not just the field: a verification hangs under the change it
69	// proves, so the original issue shows what is still unproven about it.
70	test('the verification is filed as a sub-issue of the original', () => {
71	  assert.match(skill, /sub-issue/i, 'the skill never links the verification under the change it proves');
72	  assert.match(skill, /sub_issue_write/, 'nothing says how to make the link');
73	});
74	
75	// Not-live-yet re-arms silently, by the extension the FILER stated — the run just
76	// executes its playbook, deciding nothing.
77	test('a not-yet-live run re-arms by the filed Retry-every, mark and field only', () => {
78	  assert.match(skill, /Retry-every:/);
79	  assert.match(skill, /clear the issue's\s+`task:status:\*` label/i);
80	  assert.match(skill, /No comment/i);
81	  assert.doesNotMatch(skill, /Give-up-after/, 'the give-up marker was dropped (owner, 2026-08-20)');
82	  assert.doesNotMatch(skill, /sensible/i, 'the run decides nothing — the filer stated the extension');
83	});
84	
85	// A RETRY RE-ARMS FROM NOW (#1456). The scheduler releases a sleeping item on the
86	// first hourly pass past its `Not-before`, and a busy queue adds more delay — so the
87	// old value is already in the past when the run reads it. Pushing THAT forward by
88	// `Retry-every: 1 day` can land in the past again, which re-adopts the item on the
89	// very next pass and spends a session an hour instead of a day. #1160 sat on a
90	// `Not-before` five days stale.
91	test('the re-arm is computed from now, not from the stale Not-before', () => {
92	  assert.match(skill, /now \+ `Retry-every:`/,
93	    'the playbook never says what the new instant is measured from');
94	  assert.match(skill, /never the old value/i,
95	    'nothing rules out old-value + Retry-every, the reading that re-fires every pass');
96	});
97	
98	// THE PARAMETERS LEAD THE BODY (#1456). Every field the scheduler run and the
99	// executor read is one block on the first lines, so a person can see what the run
100	// will do without hunting, and a retry rewriting `Not-before` has one place to write.
101	test('the execution parameters are one block on the body first lines', () => {
102	  assert.match(skill, /first lines/i,
103	    'nothing places the parameter block, so filers scatter the fields through the prose');
104	  const template = /```\n(Original-issue:[\s\S]*?)```/.exec(skill)?.[1] ?? '';
105	  assert.match(template, /^Model:/m,
106	    'Model: is prescribed away from the other parameters — the scattering #1160 shows');
107	});
