+  let last = null;
+  for (const m of String(text ?? '').matchAll(REQUEUE_MARKER)) last = m;
+  if (!last) return null;
+  const at = new Date(last[1]);
+  return {
+    until: Number.isNaN(at.getTime()) ? null : at.toISOString(),
+    reason: last[2].replace(/^[—\-:\s]+/, '').trim() || null,
+  };
