const LIVE_URL = 'https://x.github.io/r/stamp.json';
const VERIFY_URL = 'https://x.github.io/r/config.json';
const BODY = [
  'Verify that the mode is stamped.',
  '',
  'Original-issue: #1286',
  `Live-probe: ${LIVE_URL} :: status 200`,
  `Verify-probe: ${VERIFY_URL} :: json mode == "fleet"`,
  'Retry-every: 6 hours',
].join('\n');

