97	// The signal-collector vocabulary (DESIGN §3.3). A task collects only the union
98	// of what its due tasks declare. `fleet` is canon-only (consumers cannot declare
99	// it) — that restriction is enforced where signals are collected, not here; the
100	// shape check only asserts a declared name is a real collector.
101	export const SIGNAL_NAMES = [
102	  'commits', 'prs', 'issues', 'branches', 'release',
103	  'localPacks', 'sharedMount', 'conversationLogs', 'stamp', 'fleet', 'request',
104	];
105	
106	// Validate one task declaration. Returns an array of `{ what, fix }` problems —
107	// empty means the declaration is well-formed. Pure: no I/O, no imports of the
108	// task itself; the caller supplies the already-loaded default export.
109	export function validateTaskDeclaration(raw) {
110	  const decl = normalizeTaskDeclaration(raw);
111	  if (decl === null || typeof decl !== 'object' || Array.isArray(decl)) {
112	    return [{ what: 'task.mjs does not default-export a declaration object', fix: 'export default { id, frequency, precondition_signals, agent_model, expected_outcome, agent_instructions, precondition }' }];
113	  }
114	  const problems = [];
115	  const bad = (what, fix) => problems.push({ what, fix });
116	
117	  if (typeof decl.id !== 'string' || decl.id.trim() === '') {
118	    bad('the task has no string "id"', 'give the task an "id" matching its directory name');
119	  }
120	  // ACCEPTED, not FREQUENCIES: a member's own task file may still carry a retired spelling and
121	  // must keep running, since nothing converges a member's task files. Stopping a NEW declaration
122	  // from naming one is the author-time declaration-shape check's job, not this one's — the split
123	  // is deliberate, and `FREQUENCIES` beside `ACCEPTED_FREQUENCIES` in calendar.mjs is where it is
124	  // spelled out.
125	  if (!ACCEPTED_FREQUENCIES.includes(decl.frequency)) {
126	    bad(`"frequency" ${JSON.stringify(decl.frequency)} is not a legal frequency`, `set one of: ${ACCEPTED_FREQUENCIES.join(', ')}`);
127	  }
128	  if (!Array.isArray(decl.precondition_signals) || !decl.precondition_signals.every((s) => SIGNAL_NAMES.includes(s))) {
129	    bad(`"precondition_signals" must be an array of known signal names`, `use only: ${SIGNAL_NAMES.join(', ')}`);
